/*
 * Scotiabank header interactions, bound on existing nav markup: the markup server-rendered by the
 * AEM header component (scotia/components/header, header Experience Fragment) or the fallback built
 * by blocks/header from the EDS nav fragment. Self-contained (no imports): also shipped in the AEM
 * clientlib (aem-scotia clientlib-site js/nav.js, generated by tools/sync-from-eds.mjs).
 */

// prod (bootstrap) breakpoints: < 768 mobile, 768-991 tablet, >= 992 desktop (>= 1200 wide)
const isDesktop = window.matchMedia('(min-width: 992px)');
const isMobile = window.matchMedia('(max-width: 767px)');
const SEARCH_URL = 'https://www.scotiabank.com/ca/en/search-results.html';

const search = (q) => {
  window.location.href = `${SEARCH_URL}${q ? `?q=${encodeURIComponent(q)}` : ''}`;
};

/** site path of a URL: without the AEM site root (/content/<site>), extension and trailing slash */
const sitePath = (href) => {
  try {
    return new URL(href, window.location).pathname
      .replace(/^\/content\/[^/]+(?=\/)/, '').replace(/\.html$/, '').replace(/\/$/, '');
  } catch { return ''; }
};

/** top bar: current segment (longest segment path containing the page, as prod), language menu */
function initTopbar(nav) {
  const current = sitePath(window.location.href);
  const active = [...nav.querySelectorAll('.nav-segments a')]
    .map((a) => ({ a, path: sitePath(a.href) }))
    .filter(({ path }) => path && (current === path || current.startsWith(`${path}/`)))
    .sort((x, y) => y.path.length - x.path.length)[0];
  if (active) {
    active.a.classList.add('active');
    active.a.setAttribute('aria-current', 'page');
  }

  const lang = nav.querySelector('.nav-lang');
  const toggle = lang?.querySelector('.nav-lang-toggle');
  const langList = lang?.querySelector('.nav-lang-menu');
  if (!toggle || !langList) return;
  const setOpen = (open) => {
    lang.classList.toggle('open', open);
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    // like prod (Popper), keep the menu 5px inside the viewport
    langList.style.left = '';
    if (open) {
      const r = langList.getBoundingClientRect();
      const overflow = r.right - (document.documentElement.clientWidth - 5);
      if (overflow > 0) langList.style.left = `${-overflow}px`;
    }
  };
  toggle.addEventListener('click', () => setOpen(!lang.classList.contains('open')));
  lang.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && lang.classList.contains('open')) { setOpen(false); toggle.focus(); }
  });
  document.addEventListener('click', (e) => { if (!lang.contains(e.target)) setOpen(false); });
}

/** search box with the trending searches panel */
function initSearch(nav) {
  const box = nav.querySelector('.nav-search-box');
  const form = box?.querySelector('.nav-search');
  if (!form) return;
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    search(form.querySelector('input').value.trim());
  });
  if (!box.querySelector('.nav-trending')) return;
  const input = form.querySelector('input');
  const setOpen = (open) => box.classList.toggle('open', open);
  input.addEventListener('focus', () => setOpen(true));
  box.addEventListener('focusout', (e) => { if (!box.contains(e.relatedTarget)) setOpen(false); });
  box.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { setOpen(false); input.blur(); }
  });
  document.addEventListener('mousedown', (e) => { if (!box.contains(e.target)) setOpen(false); });
}

/** desktop mega-menu: hover / keyboard / focus */
function initMenu(nav) {
  const categories = [...nav.querySelectorAll('.nav-menu > ul > li.has-dropdown')]
    .map((li) => ({ li, link: li.querySelector(':scope > a') }))
    .filter((cat) => cat.link);
  const close = (cat) => {
    cat.li.classList.remove('open');
    cat.link.setAttribute('aria-expanded', 'false');
  };
  const open = (cat) => {
    categories.filter((c) => c !== cat).forEach(close);
    cat.li.classList.add('open');
    cat.link.setAttribute('aria-expanded', 'true');
  };
  categories.forEach((cat) => {
    cat.li.addEventListener('mouseenter', () => { if (isDesktop.matches) open(cat); });
    cat.li.addEventListener('mouseleave', () => { if (isDesktop.matches) close(cat); });
    // keyboard: Enter follows the link (as prod), Space / ArrowDown opens the panel, Escape closes
    cat.link.addEventListener('keydown', (e) => {
      if (e.key === ' ' || e.key === 'ArrowDown') {
        e.preventDefault();
        open(cat);
        cat.li.querySelector('.nav-dropdown a')?.focus();
      }
    });
    cat.li.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && cat.li.classList.contains('open')) {
        close(cat);
        cat.link.focus();
      }
    });
    cat.li.addEventListener('focusout', (e) => { if (!cat.li.contains(e.relatedTarget)) close(cat); });
  });
}

/** prod-like mobile/tablet drawer ("mav"): root list > category panel > section panel */
function initDrawer(nav) {
  const drawer = nav.querySelector('.nav-drawer');
  const toggleButton = nav.querySelector('.nav-hamburger button');
  if (!drawer || !toggleButton) return;
  const wrapper = drawer.querySelector('.nav-drawer-wrapper');
  const panels = [...drawer.querySelectorAll('.nav-drawer-panel')];
  const root = panels[0];
  const show = (panel, focus = true) => {
    if (!panel) return;
    panels.forEach((p) => p.classList.toggle('active', p === panel));
    if (wrapper) wrapper.scrollTop = 0;
    if (focus) panel.querySelector('a, button, select')?.focus({ preventScroll: true });
  };
  drawer.querySelectorAll('.nav-drawer-toggle, .nav-drawer-back').forEach((b) => {
    b.addEventListener('click', () => show(drawer.querySelector(`#${b.getAttribute('aria-controls')}`)));
  });

  const searchForm = drawer.querySelector('.nav-drawer-search');
  searchForm?.addEventListener('submit', (e) => {
    e.preventDefault();
    search(searchForm.querySelector('input').value.trim());
  });
  // mobile search focus: prod shows the trending searches sheet over the drawer
  const input = searchForm?.querySelector('input');
  const dismiss = drawer.querySelector('.nav-drawer-dismiss');
  if (input && dismiss) {
    const setSearch = (open) => drawer.classList.toggle('search-open', open);
    input.addEventListener('focus', () => setSearch(true));
    dismiss.addEventListener('click', () => { setSearch(false); input.blur(); });
    drawer.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && drawer.classList.contains('search-open')) {
        e.stopPropagation();
        setSearch(false);
        input.blur();
      }
    });
  }

  // drawer selects: current segment preselected, navigate on change
  const sites = drawer.querySelector('#nav-drawer-sites');
  const active = nav.querySelector('.nav-segments a.active');
  if (sites && active) {
    [...sites.options].forEach((o) => { o.selected = o.value === active.href; });
  }
  drawer.querySelectorAll('select').forEach((sel) => {
    sel.addEventListener('change', () => { window.location.href = sel.value; });
  });

  const resetPanels = () => {
    drawer.classList.remove('search-open');
    show(root, false);
  };
  const overlay = nav.querySelector('.nav-overlay');
  const setDrawer = (open) => {
    nav.classList.toggle('drawer-open', open);
    toggleButton.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggleButton.setAttribute('aria-label', open ? 'Close menu' : 'Menu');
    drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
    document.body.classList.toggle('nav-drawer-open', open);
    if (open) resetPanels();
    else toggleButton.focus({ preventScroll: true });
  };
  toggleButton.addEventListener('click', () => setDrawer(!nav.classList.contains('drawer-open')));
  overlay?.addEventListener('click', () => setDrawer(false));
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && nav.classList.contains('drawer-open') && !drawer.classList.contains('search-open')) setDrawer(false);
  });
  isDesktop.addEventListener('change', () => { if (isDesktop.matches) setDrawer(false); });
  isMobile.addEventListener('change', () => resetPanels());
}

/**
 * Binds every header interaction on a nav element (nav#nav).
 * @param {Element} nav the nav element
 */
export default function initNav(nav) {
  if (!nav || nav.dataset.navInit) return;
  nav.dataset.navInit = 'true';
  initTopbar(nav);
  initSearch(nav);
  initMenu(nav);
  initDrawer(nav);
}
